import React from 'react';
import { CodeSnippet } from 'carbon-components-react';

function App() {
  const [isDisabled, setIsDisabled] = React.useState(true);

  return (
    <div>
      <h1>Twilio account information</h1>
      <p>WhatsApp integration requires Twilio, see setup details below, and find your credentials on Twilio.</p>
      <div>
        <label>WhatsApp Webhook</label>
        <CodeSnippet
          type="single"
          feedback="Copied!"
          disabled={isDisabled}
          onClick={() => setIsDisabled(!isDisabled)}
        >
          {isDisabled ? 'Loading...' : 'https://integrations.us-south.assistant.dev.watson.cloud'}
        </CodeSnippet>
      </div>
    </div>
  );
}

export default App;
